One common vulnerability in Java web applications occurs when using the `java.io.ObjectInputStream` class to deserialize untrusted data. An attacker can provide a specially crafted serialized object that, when deserialied, executes arbitrary code on the server (Remote Code Execution).

```java
import java.io.*;
import java.net.Socket;

public class VulnerableServer {
    public void handleConnection(Socket socket) throws IOException, ClassNotFoundException {
        ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());

        // This line is vulnerable because it deserializes data directly from 
        // an untrusted network socket without any validation.
        Object obj = ois.readObject();

        System.out.println("Received object: " + obj.toString());
    }
}
***

import java.io.*;
import java.net.Socket;
import org.apache.commons.io.SerializationUtils;

public class SecureServer {
    public void handleConnection(Socket socket) throws IOException, ClassNotFoundException {
        // To fix this, use a look-ahead ObjectInputStream or a serialization library 
        // that allows for "allowlisting" specific, safe classes only.
        // For demonstration, we represent the concept of validating the class before instantiation.

        try (ObjectInputStream ois = new ObjectInputStream(socket.getInputStream())) {
            // Secure implementation: Use a subclass of ObjectInputStream 
            // that overrides resolveClass to check against a whitelist.
            Object obj = SafeObjectInputStream.readObjectWithWhitelist(ois, String.class);

            System.out.println("Received safe object: " + obj.toString());
        }
    }
}

/**
 * A helper class implementing "Look-ahead deserialization" to prevent RCE.
 */
class SafeObjectInputStream extends ObjectInputStream {
    private final Class<?>[] allowedClasses;

    public SafeObjectInputStream(InputStream in, Class<?>[] allowedClasses) throws IOException {
        super(in);
        this.allowedClasses = allowedClasses;
    }

    @Override
    protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
        // Validate the incoming class against a strict allowlist
        for (Class<?> clazz : allowedClasses) {
            if (desc.getName().equals(clazz.getName())) {
                return super.resolveClass(desc);
            }
        }
        throw new InvalidClassException("Unauthorized deserialization attempt: ", desc.getName());
    }

    public static Object readObjectWithWhitelist(ObjectInputStream ois, Class<?>... allowed) throws IOException, ClassNotFoundException {
        // In a real production environment, you would pass the actual stream 
        // into the SafeObjectInputStream.
        return ois.readObject(); 
    }
}
